from collections import Counter,deque
R,C=len(di),len(di[0]); print(R,C,Counter(x for row in di for x in row))
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  v=di[r][c]
  if v==3 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); pts=[]
  while q:
   a,b=q.pop();pts.append((a,b))
   for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
    x,y=a+da,b+db
    if 0<=x<R and 0<=y<C and di[x][y]==v and (x,y) not in seen:
     seen.add((x,y));q.append((x,y))
  comps.append((v,len(pts),min(a for a,b in pts),max(a for a,b in pts),min(b for a,b in pts),max(b for a,b in pts)))
print(sorted(comps,key=lambda x:-x[1]))
